const rows=window.ENERGY_DATA;
const state={view:'overview',mode:'business',selected:'United States',reference:'China',compare:['United States','China','Germany','Croatia'],usage:1000000,unit:'kWh',query:'',sort:'price',direction:-1};
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=v=>v===''||v==null?null:Number(v);
const get=name=>rows.find(r=>r.country===name), selected=()=>get(state.selected), reference=()=>get(state.reference), price=r=>num(r[`${state.mode}_price_usd_per_kwh`]);
const fmt=(v,d=2)=>v===null||!Number.isFinite(v)?'Unavailable':v.toLocaleString('en-US',{minimumFractionDigits:d,maximumFractionDigits:d});
const money=v=>v===null?'Unavailable':new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(v);
const rate=v=>v===null?'Unavailable':'$'+fmt(v,3);
const qty=()=>Number.isFinite(state.usage)&&state.usage>=0?state.usage*(state.unit==='MWh'?1000:1):null;
const spend=r=>qty()===null||price(r)===null?null:qty()*price(r);
const sorted=()=>rows.filter(r=>price(r)!==null).sort((a,b)=>price(b)-price(a));
const difference=(a,b)=>a===null||b===null?null:a-b;
const pct=(a,b)=>a===null||b===null||b===0?null:100*(a-b)/b;
const fuels=[['solar','Solar','#e5b23f'],['wind','Wind','#5d96c6'],['oil_and_other_fossil','Oil & other fossil','#9b809e'],['gas','Gas','#87a7b6'],['coal','Coal','#364c65'],['hydro','Hydro','#287db6'],['other','Other','#b7c4d8']];
function mix(r,primary=false){return fuels.map(([k,label,color])=>({label:primary&&k==='oil_and_other_fossil'?'Oil':label,color,value:num(r[`${primary?'primary_energy_consumption':'electricity_generation'}_${primary&&k==='oil_and_other_fossil'?'oil':k}_pct`])}));}
function stack(r,primary=false,full=false){const a=mix(r,primary);return `<div class="stacked" role="img" aria-label="${esc(r.country)} ${primary?'primary-energy consumption':'domestic electricity generation'} mix: ${a.map(x=>`${x.label} ${fmt(x.value)}%`).join(', ')}">${a.map(x=>`<span style="width:${x.value??0}%;background:${x.color}" title="${x.label}: ${fmt(x.value)}%"></span>`).join('')}</div><div class="${full?'mix-values':'legend'}">${a.map(x=>full?`<div><i style="background:${x.color}"></i>${x.label}<strong>${fmt(x.value)}%</strong></div>`:`<span class="legend-item"><i style="background:${x.color}"></i>${x.label}</span>`).join('')}</div>`;}
function stat(label,value){return `<div><dt>${label}</dt><dd>${value}</dd></div>`;}
function profileButton(r,label='View country brief →'){return `<button class="text-button" data-profile="${esc(r.country)}">${label}</button>`;}
function metric(label,value,note,feature=false){return `<article class="metric ${feature?'feature':''}"><div class="metric-label">${label}</div><div class="metric-value">${value}</div><div class="metric-note">${note}</div></article>`;}
function overview(){const rank=sorted(),s=selected(),r=reference(),p=price(s),rp=price(r),delta=pct(p,rp);const max=price(rank[0]);return `<section class="metrics" aria-label="Key electricity prices">${metric('Selected · '+esc(s.country),rate(p),`${state.mode==='business'?'Business':'Household'} electricity · USD/kWh`,true)}${metric('Highest in sample',rate(max),esc(rank[0].country))}${metric('Lowest in sample',rate(price(rank.at(-1))),esc(rank.at(-1).country))}${metric('Vs. '+esc(r.country),delta===null?'Unavailable':`${delta>0?'+':''}${fmt(delta,1)}%`,delta===null?'Comparison requires both prices':(delta===0?'Same recorded price':`${rate(Math.abs(p-rp))}/kWh ${delta>0?'higher':'lower'}`))}</section><div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><h2>Electricity prices by country</h2><p>Ranked within this ${rows.length}-country sample</p></div><span class="tag">USD / kWh</span></div><div class="chart"><div class="chart-key"><span><i class="key" style="background:var(--blue)"></i>Selected</span><span><i class="key" style="background:var(--navy)"></i>Reference</span><span><i class="key" style="background:#adc2dd"></i>Other countries</span></div>${rank.map((x,i)=>`<button class="bar-row ${x.country===state.selected?'selected':x.country===state.reference?'reference':''}" data-profile="${esc(x.country)}" aria-label="${esc(x.country)}, rank ${i+1} in sample, ${rate(price(x))} per kWh. Open country brief"><span class="rank">${String(i+1).padStart(2,'0')}</span><span class="country-name">${esc(x.country)}</span><span class="bar-track"><span class="bar-fill" style="display:block;width:${price(x)/max*100}%"></span></span><span class="bar-number">${fmt(price(x),3)}</span></button>`).join('')}<p class="footnote">${rank.length} available prices · ${rows.filter(x=>price(x)===null).map(x=>esc(x.country)).join(', ')} unavailable. Select a country to see its sources.</p></div></section><div class="right-stack"><section class="panel insight-panel"><div class="insight-label">THE COST DIFFERENCE</div><div class="insight-number">${delta===null?'—':fmt(Math.abs(delta),1)+'%'}</div><p class="insight-copy">${delta===null?'A price comparison is unavailable for this selection.':delta===0?`The recorded electricity price is the same in <strong>${esc(s.country)}</strong> and <strong>${esc(r.country)}</strong>.`:`Electricity in <strong>${esc(s.country)}</strong> costs <strong>${delta>0?'more':'less'}</strong> per kWh than in ${esc(r.country)}.`}</p><button class="text-button" data-view="calculator">Translate prices into annual spending →</button></section><section class="panel spotlight"><div class="spotlight-title"><div><p class="eyebrow">COUNTRY SPOTLIGHT</p><h2>${esc(s.country)}</h2></div><span class="tag">2024 MIX</span></div><p class="subtle">Domestic electricity generation</p>${stack(s)}<dl class="stat-list">${stat('Generation · 2024',fmt(num(s.electricity_domestic_generation_twh))+' TWh')}${stat('Net imports · 2024',fmt(num(s.electricity_net_imports_twh))+' TWh')}${stat('Global energy-use rank · 2024','#'+s.total_energy_consumption_rank)}</dl><p class="footnote">“Other” includes nuclear and other renewables.</p><div style="margin-top:18px">${profileButton(s)}</div></section></div></div>`;}
function render(){document.querySelectorAll('.nav').forEach(b=>{b.classList.toggle('active',b.dataset.view===state.view);if(b.dataset.view===state.view)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});document.querySelectorAll('[data-mode]').forEach(b=>{b.classList.toggle('active',b.dataset.mode===state.mode);b.setAttribute('aria-pressed',b.dataset.mode===state.mode);});$('#selected').value=state.selected;$('#reference').value=state.reference;$('#view').innerHTML=({overview,compare:comparison,calculator,mix:energyMix,data:dataView})[state.view]();}
for(const id of ['selected','reference']){const el=$('#'+id);el.innerHTML=[...rows].sort((a,b)=>a.country.localeCompare(b.country)).map(r=>`<option>${esc(r.country)}</option>`).join('');el.addEventListener('change',()=>{state[id]=el.value;render();});}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.view){state.view=b.dataset.view;render();}if(b.dataset.mode){state.mode=b.dataset.mode;render();}if(b.dataset.profile)showProfile(b.dataset.profile);});
function usageInputs(){return `<div class="usage-row"><label>Annual electricity usage<input id="usage" type="number" min="0" max="1000000000000" step="any" value="${Number.isFinite(state.usage)?state.usage:''}" inputmode="decimal" aria-describedby="usage-note"></label><label>Unit<select id="unit"><option ${state.unit==='kWh'?'selected':''}>kWh</option><option ${state.unit==='MWh'?'selected':''}>MWh</option></select></label></div><p id="usage-note" class="footnote">Enter a nonnegative annual usage. 1 MWh = 1,000 kWh.</p>`;}
function comparison(){return `<div class="section-top"><div><h2>Put your markets side by side.</h2><p class="section-description">Compare up to four countries at the same annual electricity usage.</p></div><span class="tag">${state.compare.length} / 4 COUNTRIES</span></div><section class="panel"><div class="compare-toolbar"><div class="search-picker"><label for="country-search">Find a country to add</label><input id="country-search" type="search" placeholder="Search all 16 countries…" autocomplete="off" aria-controls="country-results"><div id="country-results" class="picker-list"></div></div><div class="chips">${state.compare.map(n=>`<span class="chip">${esc(n)}<button data-remove="${esc(n)}" aria-label="Remove ${esc(n)} from comparison">×</button></span>`).join('')}</div></div><div class="section-padding" style="border-top:1px solid var(--line);max-width:520px">${usageInputs()}</div></section><div id="compare-cards">${compareCards()}</div><p class="footnote">Illustrative spending at the recorded ${state.mode} rate, not a quote or forecast. Business rates assume 1,000,000 kWh/year; other volumes assume the same unit rate.</p>`;}
function compareCards(){return state.compare.length?`<div class="comparison-cards">${state.compare.map(n=>{const r=get(n);return `<article class="comparison-card"><h3>${profileButton(r,esc(n))}</h3><p class="subtle">${state.mode==='business'?'Business':'Household'} · December 2025</p><div class="big-price">${rate(price(r))}<small class="subtle"> / kWh</small></div><dl class="stat-list">${stat('Annual spending',money(spend(r)))}${stat('Difference vs. '+esc(state.reference),money(difference(spend(r),spend(reference()))))}</dl><h3 style="margin-top:24px">Electricity mix · ${r.mix_year}</h3>${stack(r)}<dl class="stat-list" style="margin-top:18px">${stat('Generation · 2024',fmt(num(r.electricity_domestic_generation_twh))+' TWh')}${stat('Gross imports · 2024',fmt(num(r.electricity_gross_imports_twh))+' TWh')}${stat('Gross exports · 2024',fmt(num(r.electricity_gross_exports_twh))+' TWh')}${stat('Net imports · 2024',fmt(num(r.electricity_net_imports_twh))+' TWh')}</dl><p class="footnote">Mix is domestic generation. “Other” includes nuclear and other renewables.</p></article>`;}).join('')}</div>`:'<div class="empty">Search for a country above to start your comparison.</div>';}
function calculator(){return `<div class="section-top"><div><h2>From unit price to annual spending.</h2><p class="section-description">An illustrative comparison using the recorded electricity rates.</p></div><span class="tag">USD / YEAR</span></div><div class="calculator-grid"><section class="panel section-padding"><h3>Your electricity usage</h3><div style="margin-top:22px">${usageInputs()}</div><dl class="stat-list" style="margin-top:26px">${stat(esc(state.selected)+' rate',rate(price(selected()))+' / kWh')}${stat(esc(state.reference)+' reference',rate(price(reference()))+' / kWh')}${stat('Price period','December 2025')}</dl><p class="footnote">Spending = annual kWh × recorded USD/kWh.</p><p class="footnote">Business prices assume 1,000,000 kWh/year. Applying them to other volumes assumes the same unit rate; contracted tariffs and volume discounts are not modeled.</p></section><div id="calc-result">${calcResult()}</div></div>`;}
function calcResult(){const a=spend(selected()),b=spend(reference()),d=difference(a,b),percent=pct(a,b);return `<section class="calc-result"><p class="eyebrow">${esc(state.selected).toUpperCase()} · ANNUAL ELECTRICITY SPENDING</p><div class="metric-value">${money(a)}</div><p class="subtle">${qty()===null?'Enter a valid annual usage.':price(selected())===null?'Recorded electricity price unavailable.':fmt(qty(),0)+' kWh at '+rate(price(selected()))+'/kWh'}</p><dl class="stat-list" style="margin-top:25px">${stat(esc(state.reference)+' reference',money(b))}${stat('Annual difference',money(d))}${stat('Percentage difference',percent===null?'Unavailable':`${percent>0?'+':''}${fmt(percent,1)}%`)}</dl><p style="margin-top:22px;font-size:15px">${d===null?'Comparison unavailable: a valid usage and both countries’ prices are required.':d===0?'Both selections have the same illustrative annual spending.':`${esc(state.selected)} would cost ${money(Math.abs(d))} ${d>0?'more':'less'} per year than ${esc(state.reference)} at this usage.`}</p><p class="footnote" style="color:#c1d1e5">Illustrative spending at historical rates. Not a supplier quote or forecast.</p></section>`;}
function trade(r,total=false){const prefix=total?'total_energy':'electricity',unit=total?'ej':'twh',year=r[`${prefix}_production_trade_year`],production=num(r[total?'total_energy_domestic_production_ej':'electricity_domestic_generation_twh']),net=num(r[`${prefix}_net_imports_${unit}`]);return `<div class="panel section-padding"><p class="eyebrow">${total?'TOTAL ENERGY':'ELECTRICITY'} · ${year} · ${unit.toUpperCase()}</p><h2>${total?'Total-energy production & trade':'Electricity generation & trade'}</h2><div class="trade-metrics">${[['Domestic '+(total?'production':'generation'),production],['Gross imports',num(r[`${prefix}_gross_imports_${unit}`])],['Gross exports',num(r[`${prefix}_gross_exports_${unit}`])],['Net imports',net]].map(([label,v])=>`<div><span>${label}</span><strong>${fmt(v,total?3:2)}</strong></div>`).join('')}</div><p class="footnote">${esc(r.country)} is a net ${net>0?'importer':net<0?'exporter':'balanced trader'} of ${total?'energy':'electricity'} in ${year}. Positive net imports mean importing; negative values mean exporting.</p>${total?'<p class="footnote">EJ totals use IEA energy balances. Do not multiply consumption-mix shares by these production totals.</p>':'<p class="footnote">EIA generation totals can differ from the OWID/Ember totals behind the generation mix.</p>'}</div>`;}
function energyMix(){const r=selected();return `<div class="section-top"><div><h2>${esc(r.country)}: energy mix & trade</h2><p class="section-description">What is generated domestically, and what crosses the border.</p></div>${profileButton(r)}</div><div class="mix-layout"><section class="panel section-padding"><p class="eyebrow">DOMESTIC ELECTRICITY GENERATION · ${r.mix_year}</p><h2>Electricity generation mix</h2>${stack(r,false,true)}<p class="footnote">Shares of domestically generated electricity, not capacity or electricity consumed. “Other” includes nuclear and other renewables.</p></section>${trade(r)}</div><details class="panel" style="margin-top:24px"><summary>Primary-energy consumption and total-energy trade <span>Separate accounting basis</span></summary><div class="mix-layout section-padding"><section><p class="eyebrow">PRIMARY-ENERGY CONSUMPTION · ${r.mix_year}</p><h2>Primary-energy consumption mix</h2>${stack(r,true,true)}<p class="footnote">Includes transport and heating. Substitution-method shares; traditional biomass is excluded. These are consumption shares, not extraction or production shares.</p></section>${trade(r,true)}</div></details>`;}
const columns=[['country','Country'],['price','Electricity · USD/kWh'],['household_price_usd_per_kwh','Household · USD/kWh'],['electricity_domestic_generation_twh','Generation · TWh'],['electricity_net_imports_twh','Net imports · TWh'],['total_energy_consumption_rank','Global energy-use rank']];
function filtered(){const list=rows.filter(r=>r.country.toLowerCase().includes(state.query.toLowerCase()));return list.sort((a,b)=>{let av=state.sort==='price'?price(a):state.sort==='country'?a.country:num(a[state.sort]),bv=state.sort==='price'?price(b):state.sort==='country'?b.country:num(b[state.sort]);if(av===null)return bv===null?0:1;if(bv===null)return -1;return (typeof av==='string'?av.localeCompare(bv):av-bv)*state.direction;});}
function dataView(){return `<div class="section-top"><div><h2>The data behind the decisions.</h2><p class="section-description">Search, sort, inspect sources, or download the filtered records.</p></div></div><section class="panel"><div class="data-tools"><label>Filter countries<input id="data-query" type="search" placeholder="Search country name…" value="${esc(state.query)}"></label><button class="primary-button" id="download">Download filtered CSV ↓</button><span id="data-count" class="subtle">${filtered().length} ${filtered().length===1?'country':'countries'}</span></div><div class="table-scroll"><table><thead><tr>${columns.map(([key,title])=>`<th scope="col" aria-sort="${state.sort===key?(state.direction===1?'ascending':'descending'):'none'}"><button data-sort="${key}">${key==='price'?(state.mode==='business'?'Business':'Selected household')+' · USD/kWh':title} ${state.sort===key?(state.direction===1?'↑':'↓'):'↕'}</button></th>`).join('')}</tr></thead><tbody id="data-body">${dataRows()}</tbody></table></div><p class="table-note">Prices: December 2025 · Generation, trade and global consumption rank: 2024.<br>CSV download contains all 49 original columns for the filtered countries. Rank is the source’s global energy-consumption rank, not a price ranking.</p></section>`;}
function dataRows(){const list=filtered();return list.length?list.map(r=>`<tr><td>${profileButton(r,esc(r.country))}</td><td>${rate(price(r))}</td><td>${rate(num(r.household_price_usd_per_kwh))}</td><td>${fmt(num(r.electricity_domestic_generation_twh))}</td><td>${fmt(num(r.electricity_net_imports_twh))}</td><td>${r.total_energy_consumption_rank}</td></tr>`).join(''):'<tr><td colspan="6" class="empty">No matching countries.</td></tr>';}
function sourceLink(url,label){return /^https:\/\//.test(url)?`<a class="source-link" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`:'';}
function showProfile(name){const r=get(name);const p=price(r),rank=sorted().findIndex(x=>x.country===name);$('#profile-body').innerHTML=`<h2 id="profile-title">${esc(name)}</h2><p class="subtle">${rank>=0?'#'+(rank+1)+' in this sample by '+state.mode+' electricity price':'Electricity price unavailable'} · Global energy-consumption rank #${r.total_energy_consumption_rank} (${r.total_energy_consumption_year})</p><h3>Electricity prices · ${r.price_period}</h3><dl class="stat-list">${stat('Business · USD/kWh',rate(num(r.business_price_usd_per_kwh)))}${stat('Household · USD/kWh',rate(num(r.household_price_usd_per_kwh)))}${stat('Business · '+r.local_currency+'/kWh',fmt(num(r.business_price_local_currency_per_kwh),3))}${stat('Household · '+r.local_currency+'/kWh',fmt(num(r.household_price_local_currency_per_kwh),3))}</dl><h3>Domestic electricity generation mix · ${r.mix_year}</h3>${stack(r,false,true)}<h3>Electricity generation & trade · ${r.electricity_production_trade_year}</h3><dl class="stat-list">${stat('Domestic generation',fmt(num(r.electricity_domestic_generation_twh))+' TWh')}${stat('Gross imports',fmt(num(r.electricity_gross_imports_twh))+' TWh')}${stat('Gross exports',fmt(num(r.electricity_gross_exports_twh))+' TWh')}${stat('Net imports',fmt(num(r.electricity_net_imports_twh))+' TWh')}</dl><h3>Total energy</h3><dl class="stat-list">${stat('Consumption · '+r.total_energy_consumption_year,fmt(num(r.total_energy_consumption_exajoules))+' EJ')}${stat('Domestic production · '+r.total_energy_production_trade_year,fmt(num(r.total_energy_domestic_production_ej),3)+' EJ')}${stat('Gross imports · '+r.total_energy_production_trade_year,fmt(num(r.total_energy_gross_imports_ej),3)+' EJ')}${stat('Gross exports · '+r.total_energy_production_trade_year,fmt(num(r.total_energy_gross_exports_ej),3)+' EJ')}${stat('Net imports · '+r.total_energy_production_trade_year,fmt(num(r.total_energy_net_imports_ej),3)+' EJ')}</dl><h3>Sources & definitions</h3><p class="subtle">Recorded access date: ${r.accessed_date}</p>${sourceLink(r.price_source_url,'Electricity prices')}${sourceLink(r.consumption_source_url,'Energy consumption')}${sourceLink(r.mix_source_url,'Energy mix dataset')}${sourceLink(r.mix_definitions_url,'Mix definitions')}${sourceLink(r.total_energy_production_trade_source_url,'Total-energy balance')}${sourceLink(r.electricity_production_trade_source_url,'Electricity production & trade')}<details style="margin-top:16px"><summary>Original source notes and accounting definitions</summary>${['price_basis','notes','electricity_mix_basis','primary_energy_mix_basis','mix_notes','production_trade_notes'].map(k=>`<p class="note-block">${esc(r[k])}</p>`).join('')}</details><div style="margin-top:20px"><button class="primary-button" data-select-profile="${esc(name)}">Use as selected country</button></div>`;if(!$('#profile').open)$('#profile').showModal();$('#profile').scrollTop=0;}
function refreshUsage(){if($('#calc-result'))$('#calc-result').innerHTML=calcResult();if($('#compare-cards'))$('#compare-cards').innerHTML=compareCards();}
function picker(query){const options=rows.filter(r=>!state.compare.includes(r.country)&&r.country.toLowerCase().includes(query.toLowerCase())).sort((a,b)=>a.country.localeCompare(b.country));$('#country-results').innerHTML=state.compare.length>=4?'<p class="note-block">Four countries selected. Remove one to add another.</p>':options.length?options.map(r=>`<button data-add="${esc(r.country)}">${esc(r.country)}</button>`).join(''):'<p class="note-block">No matching countries.</p>';}
document.addEventListener('input',e=>{if(e.target.id==='usage'){state.usage=e.target.value===''?NaN:Number(e.target.value);if(state.usage>1e12)state.usage=NaN;refreshUsage();}if(e.target.id==='country-search')picker(e.target.value);if(e.target.id==='data-query'){state.query=e.target.value;$('#data-body').innerHTML=dataRows();$('#data-count').textContent=filtered().length+(filtered().length===1?' country':' countries');}});
document.addEventListener('focusin',e=>{if(e.target.id==='country-search')picker(e.target.value);});
document.addEventListener('change',e=>{if(e.target.id==='unit'){const old=state.unit;state.unit=e.target.value;state.usage*=old==='MWh'?1000:1/1000;if($('#usage'))$('#usage').value=Number.isFinite(state.usage)?state.usage:'';refreshUsage();}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#country-results'))$('#country-results').innerHTML='';if(e.key==='ArrowDown'&&e.target.id==='country-search'){e.preventDefault();$('#country-results button')?.focus();}});
document.addEventListener('click',e=>{if(!e.target.closest('.search-picker')&&$('#country-results'))$('#country-results').innerHTML='';const b=e.target.closest('button');if(!b)return;if(b.dataset.add&&state.compare.length<4&&!state.compare.includes(b.dataset.add)){state.compare.push(b.dataset.add);render();$('#announcement').textContent=b.dataset.add+' added to comparison';$('#country-search')?.focus();}if(b.dataset.remove){state.compare=state.compare.filter(x=>x!==b.dataset.remove);render();$('#country-search')?.focus();}if(b.dataset.sort){if(state.sort===b.dataset.sort)state.direction*=-1;else{state.sort=b.dataset.sort;state.direction=state.sort==='country'?1:-1;}render();}if(b.dataset.selectProfile){state.selected=b.dataset.selectProfile;$('#profile').close();render();}if(b.id==='download'){const list=filtered(),keys=Object.keys(rows[0]);const quote=v=>'"'+String(v??'').replaceAll('"','""')+'"';const csv=[keys,...list.map(r=>keys.map(k=>r[k]))].map(r=>r.map(quote).join(',')).join('\r\n');const blob=new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='energy-comparison.csv';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);$('#announcement').textContent=list.length+' country records downloaded';}});
$('#close-profile').onclick=()=>$('#profile').close();$('#profile').addEventListener('click',e=>{if(e.target===$('#profile')){const b=e.target.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)e.target.close();}});
render();
if(document.modelContext?.registerTool){
 const lifecycle=new AbortController();
 try{Promise.resolve(document.modelContext.registerTool({name:'configure_energy_comparison',title:'Configure energy comparison',description:'Set selected and reference countries, customer type and optional annual usage, then show the electricity spending comparison. Changes only the visible dashboard state.',inputSchema:{type:'object',properties:{country:{type:'string',enum:rows.map(r=>r.country)},reference:{type:'string',enum:rows.map(r=>r.country)},customer:{type:'string',enum:['business','household']},annual_usage_kwh:{type:'number',minimum:0,maximum:1e12}},required:['country','reference','customer'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input!=='object'||!get(input.country)||!get(input.reference)||!['business','household'].includes(input.customer)||Object.keys(input).some(k=>!['country','reference','customer','annual_usage_kwh'].includes(k)))throw new Error('Invalid country, reference or customer type.');if(input.annual_usage_kwh!==undefined&&(!Number.isFinite(input.annual_usage_kwh)||input.annual_usage_kwh<0||input.annual_usage_kwh>1e12))throw new Error('Annual usage must be between 0 and 1 trillion kWh.');state.selected=input.country;state.reference=input.reference;state.mode=input.customer;if(input.annual_usage_kwh!==undefined){state.usage=input.annual_usage_kwh;state.unit='kWh';}state.view='calculator';render();return {country:state.selected,reference:state.reference,customer:state.mode,annual_usage_kwh:qty(),country_annual_usd:spend(selected()),reference_annual_usd:spend(reference()),difference_usd:difference(spend(selected()),spend(reference()))};}},{signal:lifecycle.signal})).catch(()=>{});}catch{}
 window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}
